/* clean_bridge.c — bind the clean-room game/ source into the recomp runtime.
 *
 * game/bind.c provides WEAK guest_at()/guest_of() backed by a private test
 * arena. This file supplies the STRONG runtime versions so clean functions
 * read/write the real emulated memory:
 *   guest 0x80xxxxxx / KSEG mirrors -> runtime main RAM (2MB, phys-folded)
 *   guest 0x1F800000..0x1F8003FF   -> 1KB scratchpad
 *   anything else (MMIO/open bus)  -> dummy page (reads ~0, writes dropped)
 *
 * src/clean_table.c (generated by game/gen_clean_table.py) wraps each clean
 * function with a CPUState adapter; clean_try_dispatch() is called from
 * psx_dispatch_game_compiled() before the generated-code path.
 */
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <stdio.h>
#include "cpu_state.h"
#include "interrupts.h"
#include "psx_cycles.h"

extern uint8_t *memory_get_ram_ptr(void);
extern uint8_t *memory_get_scratchpad_ptr(void);
extern uint8_t  psx_read_byte(uint32_t addr);
extern uint16_t psx_read_half(uint32_t addr);
extern uint32_t psx_read_word(uint32_t addr);
extern void     psx_write_byte(uint32_t addr, uint8_t val);
extern void     psx_write_half(uint32_t addr, uint16_t val);
extern void     psx_write_word(uint32_t addr, uint32_t val);

#define BR2_RAM_SIZE        (2u * 1024u * 1024u)
#define BR2_SCRATCH_BASE    0x1F800000u
#define BR2_SCRATCH_SIZE    0x400u

/* Open-bus stand-in for addresses guest_at() cannot back with real memory
 * (MMIO regs, unmapped space). Indexed like bind.c so distinct guest addrs do
 * not alias each other. The base is masked to 64KB, but callers treat the
 * result as a struct/array and index it by UNMASKED field offsets — and some
 * paths memcpy() variable lengths through it. The arena must therefore be far
 * larger than 64KB: g_clean_cpu sits immediately after this buffer in .bss, so
 * an undersized arena lets a guest-indexed store run off the end and corrupt
 * the CPUState* (observed: g_clean_cpu=0x16f5555fa wild stack value). 1MiB
 * absorbs any realistic struct/array access; .bss is lazily committed. */
static uint8_t g_openbus[0x100000];
/* Boundary-inclusive mapping: guest code uses region-top addresses
 * (0x80200000 RAM end, 0x1F800400 scratchpad end) as EXCLUSIVE loop bounds
 * materialized through guest_at(). Returning the open-bus mirror for those
 * exact addresses breaks every `p < guest_at(end)` comparison — the pointer
 * lands in a different host buffer and the loop wipes everything between
 * (observed: scratch_zero_reset zeroed _MergedGlobals incl. the game-backend
 * registry). Map the exact tops to the contiguous one-past pointer; the
 * runtime buffers carry BR2_BOUNDARY_PAD slack so a stray deref stays
 * in-bounds and behaves like open bus (~0, writes dropped into pad). */
#define BR2_BOUNDARY_PAD 256u

static uint32_t br2_phys(uint32_t addr)
{
    uint32_t phys = addr & 0x1FFFFFFFu;
    if (phys == BR2_RAM_SIZE) return phys;      /* exclusive RAM top */
    if (phys < 0x00800000u) phys &= (BR2_RAM_SIZE - 1u);
    return phys;
}

void *guest_at(uint32_t addr)
{
    /* gwatch: close any pending watched-write window. Clean-C stores go
     * through raw guest_at() pointers and bypass every traced write path —
     * this hook is what lets the mprotect watch finish entries for exactly
     * the writers it exists to observe. One volatile load when disarmed. */
    { extern volatile int g_guest_watch_pending;
      extern void guest_watch_block_tick(void);
      if (g_guest_watch_pending) guest_watch_block_tick(); }
    uint32_t phys = br2_phys(addr);
    /* DIAG: vector-page access hunt (BR2 0x80000080 fight-init corruption).
     * Clean-C stores bypass psx_write_*; guest_at() is the one funnel they
     * all pass through. Log accesses landing in the vector page so the
     * corrupting writer's caller can be symbolized.
     * Rate-limited: phys 0x80-0xC0 is valid low main RAM (kernel workspace),
     * and faithful guest code legitimately reads it (e.g. fighter_trail_emit
     * -> prim_task_run with a NULL trail-slot base +0xa0). An unbounded
     * fprintf+fflush per access storms stderr and starves the heartbeat
     * watchdog, so only the first hits are recorded. */
    if (phys >= 0x80u && phys < 0xC0u) {
        static int s_vecga_n;
        if (s_vecga_n < 256) {
            s_vecga_n++;
            fprintf(stderr, "VECGA addr=0x%08X phys=0x%03X ra0=%p\n",
                    addr, phys, __builtin_return_address(0));
            fflush(stderr);
        }
    }
    /* Low guest addresses (<0x10000 KUSEG) map to real main RAM phys
     * 0x0000-0xFFFF — valid, readable/writable PSX memory (kernel low
     * workspace AND game structures that legitimately live there, e.g. the
     * CD dir-entry table whose base cell 0x801fc6c0 can hold 0). On real HW
     * a KUSEG access here reaches the same bytes a KSEG0 0x8000xxxx access
     * does; diverting it to a zeroed dummy made clean-C readers (cd_channel_
     * poll, cd_dir_entry_finalize, ...) see zeros while generated code read
     * the real entries -> clean/generated state divergence -> CD stream
     * deadlock. Return real RAM so both views agree. Stray NULL-deref
     * writes are the upstream port bugs they always were; absorbing them
     * here only hid the divergence. */
    if (phys <= BR2_RAM_SIZE)
        return memory_get_ram_ptr() + phys;
    if (phys >= BR2_SCRATCH_BASE && phys <= BR2_SCRATCH_BASE + BR2_SCRATCH_SIZE)
        return memory_get_scratchpad_ptr() + (phys - BR2_SCRATCH_BASE);
    return g_openbus + (addr & 0xFFFFu);
}

uint32_t guest_of(const void *p)
{
    const uint8_t *b = (const uint8_t *)p;
    uint8_t *ram = memory_get_ram_ptr();
    uint8_t *spad = memory_get_scratchpad_ptr();
    if (b >= ram && b <= ram + BR2_RAM_SIZE)
        return 0x80000000u | (uint32_t)(b - ram);
    if (b >= spad && b <= spad + BR2_SCRATCH_SIZE)
        return BR2_SCRATCH_BASE | (uint32_t)(b - spad);
    return 0;
}

/* Resolve a value that may be a host pointer into guest RAM (or scratchpad)
 * OR an already-guest address, to the canonical guest address. Clean ports
 * sometimes store pointer/link fields as `(undefined4)(uintptr_t)ptr`,
 * truncating a host address to 32 bits — garbage when the guest reads it as
 * an address. br2_gaddr yields the real guest address for host pointers and
 * passes guest-address values through unchanged. */
uint32_t br2_gaddr(const void *p)
{
    uint32_t g = guest_of(p);
    if (g) return g;
    /* Fallback diagnostic: a real host pointer (>4GB) that guest_of cannot map
     * back to a guest address means the caller passed a host ptr living outside
     * emulated RAM/scratchpad (e.g. g_openbus or a bogus ptr). Record it so
     * freeze_check can name the producer. Guest-address values (<4GB) pass
     * through unchanged and are ignored here. */
    uintptr_t up = (uintptr_t)p;
    if (up > 0x100000000ULL) {
        extern uint32_t g_bg_hi, g_bg_lo, g_bg_count;
        g_bg_count++;
        g_bg_hi = (uint32_t)(up >> 32);
        g_bg_lo = (uint32_t)up;
    }
    return (uint32_t)up;
}

/* ── MMIO-aware accessors ─────────────────────────────────────────────────
 * guest_at() can only back RAM and scratchpad with real pointers; every
 * other guest address (0x1F800400.. up — CD/GPU/DMA/timer/SIO/SPU regs,
 * BIOS ROM, open bus) must go through the runtime's load/store path so the
 * device model sees the access. The br2_ldN / br2_stN helpers pick the
 * fast pointer path for direct-mappable addresses and psx_read_* /
 * psx_write_* otherwise.
 * The *p variants resolve a pointer cell first (the cell itself is always
 * RAM), matching the DB8P/DB16P/DB32P macro contract. */
static int br2_addr_direct(uint32_t addr)
{
    uint32_t phys = addr & 0x1FFFFFFFu;
    if (phys < 0x00800000u) phys &= (BR2_RAM_SIZE - 1u);
    if (phys <= BR2_RAM_SIZE) return 1;
    if (phys >= BR2_SCRATCH_BASE && phys < BR2_SCRATCH_BASE + BR2_SCRATCH_SIZE) return 1;
    return 0;
}

uint8_t  br2_ld8 (uint32_t a) { return br2_addr_direct(a) ? *(uint8_t  *)guest_at(a) : psx_read_byte(a); }
uint16_t br2_ld16(uint32_t a) { return br2_addr_direct(a) ? *(uint16_t *)guest_at(a) : psx_read_half(a); }
uint32_t br2_ld32(uint32_t a) { return br2_addr_direct(a) ? *(uint32_t *)guest_at(a) : psx_read_word(a); }
void br2_st8 (uint32_t a, uint8_t  v) { if (br2_addr_direct(a)) *(uint8_t  *)guest_at(a) = v; else psx_write_byte(a, v); }
void br2_st16(uint32_t a, uint16_t v) { if (br2_addr_direct(a)) *(uint16_t *)guest_at(a) = v; else psx_write_half(a, v); }
void br2_st32(uint32_t a, uint32_t v) { if (br2_addr_direct(a)) *(uint32_t *)guest_at(a) = v; else psx_write_word(a, v); }

uint8_t  br2_ld8p (uint32_t cell) { return br2_ld8 (*(uint32_t *)guest_at(cell)); }
uint16_t br2_ld16p(uint32_t cell) { return br2_ld16(*(uint32_t *)guest_at(cell)); }
uint32_t br2_ld32p(uint32_t cell) { return br2_ld32(*(uint32_t *)guest_at(cell)); }
void br2_st8p (uint32_t cell, uint8_t  v) { br2_st8 (*(uint32_t *)guest_at(cell), v); }
void br2_st16p(uint32_t cell, uint16_t v) { br2_st16(*(uint32_t *)guest_at(cell), v); }
void br2_st32p(uint32_t cell, uint32_t v) { br2_st32(*(uint32_t *)guest_at(cell), v); }

/* ── BIOS service bridge ──────────────────────────────────────────────────
 * game/ ports express BIOS kernel calls as bios_svc(table, svc, a0, a1)
 * where `table` is the call vector (0xA0/0xB0/0xC0 physical) and `svc` is the
 * function number the guest trampoline places in $t1 before `jr $t2`. The
 * faithful execution is a real nested guest call into the recompiled BIOS:
 * set the argument registers, leave $ra at the clean function's own return
 * address (the BIOS service returns to it, which is exactly the stop_addr
 * contract psx_dispatch_call() implements), dispatch, and return $v0.
 * a2/a3 are intentionally not touched — the guest trampolines forward
 * whatever the caller left in them. */
static CPUState *g_clean_cpu;

void clean_bridge_set_cpu(CPUState *cpu) { g_clean_cpu = cpu; }

/* clean_cpu_state — expose the live CPUState to the clean C ports so COP2/GTE
 * helpers (setCopReg/getCopReg/copFunction/...) operate on the same
 * cpu->gte_data/gte_ctrl backing the generated recompiled code uses. */
CPUState *clean_cpu_state(void) { return g_clean_cpu; }

/* guest_gp — current guest $gp (r28) small-data base.  Ghidra emits
 * `unaff_gp` locals for gp-relative (offset($gp)) accesses; they must
 * resolve to the live register value, not an uninitialized local. */
uint32_t guest_gp(void)
{
    return g_clean_cpu ? g_clean_cpu->gpr[28] : 0x801beedc;
}

/* clean_caller_ra — return the guest $ra live at clean-port entry.  For a
 * clean function reached via a generated `jal`, gpr[31] still holds the
 * caller's return address (the instruction after the jal), so this names
 * the generated caller.  Used by diagnostic traces that need provenance. */
uint32_t clean_caller_ra(void)
{
    return g_clean_cpu ? g_clean_cpu->gpr[31] : 0;
}

/* br2_guest_ra_set — publish the $ra the equivalent guest code would hold
 * at this point.  BIOS services that validate their caller (OpenBIOS
 * kernel-call patch check, e.g. B0/0x57) hash/inspect the code bytes at
 * $ra; a stale dispatch ra produces "Couldn't find patch hash" -> the
 * BIOS prints "Stopping." and halts.  Clean ports call this with the
 * guest-accurate return address before such services. */
void br2_guest_ra_set(uint32_t ra)
{
    if (g_clean_cpu) g_clean_cpu->gpr[31] = ra;
}

extern void psx_dispatch_call(CPUState *cpu, uint32_t target_addr,
                              uint32_t return_addr);

/* bios_svc ring — last 256 kernel-service requests issued by clean code,
 * queryable via the debug server "bios_svc_trace" command. */
#define BR2_SVC_RING 256
typedef struct { uint32_t table, svc, a0, a1, a2, a3, ra, v0; } Br2SvcEnt;
static Br2SvcEnt g_svc_ring[BR2_SVC_RING];
static uint32_t g_svc_ring_n;
uint32_t br2_dbg_svc_count(void) { return g_svc_ring_n; }
int br2_dbg_svc_ent(uint32_t i, uint32_t out[8])
{
    uint32_t n = g_svc_ring_n;
    uint32_t avail = n > BR2_SVC_RING ? BR2_SVC_RING : n;
    if (i >= avail) return 0;
    const Br2SvcEnt *e = &g_svc_ring[(n - avail + i) % BR2_SVC_RING];
    out[0]=e->table; out[1]=e->svc; out[2]=e->a0; out[3]=e->a1;
    out[4]=e->a2;   out[5]=e->a3;   out[6]=e->ra;  out[7]=e->v0;
    return 1;
}

static void svc_record(uint32_t table, uint32_t svc, uint32_t a0, uint32_t a1,
                       uint32_t a2, uint32_t a3, uint32_t ra)
{
    uint32_t i = g_svc_ring_n % BR2_SVC_RING;
    g_svc_ring[i].table = table; g_svc_ring[i].svc = svc;
    g_svc_ring[i].a0 = a0;       g_svc_ring[i].a1 = a1;
    g_svc_ring[i].a2 = a2;       g_svc_ring[i].a3 = a3;
    g_svc_ring[i].ra = ra;       g_svc_ring[i].v0 = 0;
    g_svc_ring_n++;
}

/* Nested-call contract: generated code returns by publishing $ra into
 * cpu->pc (`cpu->pc = cpu->gpr[31]`). Parking $ra on 0 and dispatching
 * with stop_addr=0 makes the final `jr $ra` produce pc==0, which
 * psx_dispatch_impl treats as a plain C return for nested calls — no
 * stop_addr/sp matching required, and no sentinel value can leak into
 * guest registers or the stack. */
#define BR2_NESTED_RA 0u

static uint32_t svc_call(uint32_t table, uint32_t svc,
                         uint32_t a0, uint32_t a1, uint32_t a2, uint32_t a3)
{
    CPUState *cpu = g_clean_cpu;
    uint32_t ra, pc, sp;
    if (!cpu) return 0;
    ra = cpu->gpr[31];
    pc = cpu->pc;
    sp = cpu->gpr[29];
    cpu->gpr[4]  = a0;
    cpu->gpr[5]  = a1;
    cpu->gpr[6]  = a2;
    cpu->gpr[7]  = a3;
    cpu->gpr[8]  = table;           /* $t0 — some dispatchers inspect it */
    cpu->gpr[9]  = svc;             /* $t1 = kernel service number */
    cpu->gpr[10] = table;           /* $t2 = call vector (guest sets this) */
    /* Some BIOS services (e.g. B0/0x57) read $ra as an opaque token and
     * dereference it as a struct pointer.  The generated-game path always
     * presents a real guest code address there; BR2_NESTED_RA=0 feeds the
     * BIOS low-memory vectors instead and sends it down a bogus path.
     * Keep the live guest $ra when one exists and use it as the nested
     * stop_addr: the svc's final `jr $ra` lands exactly on stop_addr,
     * which psx_dispatch_impl converts to the plain-C return. */
    if (ra != 0) {
        cpu->gpr[31] = ra;
        psx_dispatch_call(cpu, table, ra);
    } else {
        cpu->gpr[31] = BR2_NESTED_RA;
        psx_dispatch_call(cpu, table, 0);
    }
    cpu->gpr[31] = ra;
    cpu->gpr[29] = sp;
    cpu->pc = pc;
    return cpu->gpr[2];             /* $v0 */
}

/* br2_irq_poll — interrupt check for clean-code busy-wait loops. Guest
 * polling loops hit psx_check_interrupts at every dispatch boundary; a
 * clean C `while(flag==0)` never leaves C, so IRQ-driven flag updates
 * (CD responses, VSync, DMA) would starve forever. Call this inside
 * tight polls — it runs the pending IRQ handler synchronously against
 * the live CPUState, exactly like a guest dispatch boundary would. */
void br2_irq_poll(void)
{
    CPUState *cpu = g_clean_cpu;
    /* Guest time must pass while clean C spins: psx_cycle_count only
     * advances on dispatch boundaries, and a `while(flag==0)` loop never
     * leaves C — CD due-cycle deadlines (Pause/Seek/ReadN completion),
     * timer countdowns and the wait loops' own timeouts would all freeze.
     * Charge a small quantum per poll; psx_advance_cycles services device
     * deadlines so no event is lost, only coarsened — exactly what a guest
     * spin loop does between its own dispatch boundaries. */
    psx_advance_cycles(256u);
    if (cpu) psx_check_interrupts_at(cpu, cpu->gpr[31]);
}

/* br2_bail_pending — nonzero while a generated-frame bail unwind
 * (g_psx_call_bail) is in flight. Clean-C polling loops that wait on guest
 * state through br2_call_generated / br2_irq_poll must test this and return
 * early: br2_call_generated no-ops on bail (it hands back the stale $v0), so
 * a `while(flag==0)` spin would keep "failing" forever and never let the
 * unwind reach the psx_call_contract frame that resolves it — the exact
 * wedge that froze mc_state_init's Pause retry (the frame ~8092 CD-loader
 * stall). This mirrors the generated code's own early-return-on-bail
 * contract, applied at the clean-C boundary. */
int br2_bail_pending(void) { return g_psx_call_bail; }

/* br2_guest_frame — guest stack frame for clean C. Guest code allocates
 * locals below $sp; clean ports must do the same whenever buffers cross
 * a guest-visible boundary (BIOS services, nested guest calls, IRQ
 * handlers) — a host stack buffer is invisible to guest code and a
 * fixed guest_sp()-N window would be overwritten by the callee's own
 * frame. Reserving below the live $sp (cpu->gpr[29] and the clean-side
 * guest_sp mirror) reproduces the guest layout exactly: nested guest
 * calls and BIOS services allocate below the reserved frame, never
 * into it. LIFO discipline via br2_guest_frame_free. */
extern uint32_t guest_sp(void);
extern void guest_sp_set(uint32_t sp);

static uint32_t g_frm_sp[32];
static int g_frm_depth;

uint32_t br2_guest_frame(uint32_t size)
{
    CPUState *cpu = g_clean_cpu;
    uint32_t sp = cpu ? cpu->gpr[29] : guest_sp();
    uint32_t ns = (sp - ((size + 15u) & ~15u)) & ~15u;
    if (g_frm_depth < 32) g_frm_sp[g_frm_depth++] = sp;
    if (cpu) cpu->gpr[29] = ns;
    guest_sp_set(ns);
    return ns;
}

void br2_guest_frame_free(void)
{
    uint32_t sp;
    if (g_frm_depth <= 0) return;
    sp = g_frm_sp[--g_frm_depth];
    if (g_clean_cpu) g_clean_cpu->gpr[29] = sp;
    guest_sp_set(sp);
}

/* call_guest — synchronous guest-function call from clean C. The guest
 * semantics are `jalr` with a0/a1 loaded and $ra = the post-call site; in
 * clean C the "post-call site" is this C frame, so the contract is:
 *   - clean-covered targets: run the clean wrapper directly on the live
 *     CPUState (args in $a0/$a1, result in $v0), preserving caller regs;
 *   - everything else: nested psx_dispatch_call with $ra parked on the
 *     sentinel — generated/game code has real frames so $ra==$stop_addr
 *     with balanced $sp returns cleanly through the dispatch contract. */
extern int clean_try_dispatch(CPUState *cpu, uint32_t addr);

uint32_t call_guest(uint32_t fn, uint32_t a, uint32_t b)
{
    CPUState *cpu = g_clean_cpu;
    uint32_t a0, a1, ra, pc, v0;
    if (!cpu || fn == 0) return 0;
    a0 = cpu->gpr[4]; a1 = cpu->gpr[5];
    ra = cpu->gpr[31]; pc = cpu->pc; v0 = cpu->gpr[2];
    cpu->gpr[4] = a;
    cpu->gpr[5] = b;
    if (clean_try_dispatch(cpu, fn)) {
        uint32_t r = cpu->gpr[2];
        cpu->gpr[4] = a0; cpu->gpr[5] = a1;
        cpu->gpr[31] = ra; cpu->pc = pc; cpu->gpr[2] = v0;
        return r;
    }
    {
        uint32_t sp = cpu->gpr[29];
        /* Same ra contract as svc_call: BIOS services inside the callee
         * may inspect $ra; use the live guest ra as stop_addr. */
        if (ra != 0) {
            cpu->gpr[31] = ra;
            psx_dispatch_call(cpu, fn, ra);
        } else {
            cpu->gpr[31] = BR2_NESTED_RA;
            psx_dispatch_call(cpu, fn, 0);
        }
        cpu->gpr[29] = sp;
    }
    {
        uint32_t r = cpu->gpr[2];
        cpu->gpr[4] = a0; cpu->gpr[5] = a1;
        cpu->gpr[31] = ra; cpu->pc = pc; cpu->gpr[2] = v0;
        return r;
    }
}

/* call_guest4 — four-argument variant of call_guest for guest `jalr`
 * sites that pass a0-a3. prim_task_run's record runner is the canonical
 * case: the generated body sets a1 = param_2 + lh(task+0xE), keeps
 * a2 = param_3, and loads a3 = record[1] before every indirect call, so a
 * two-argument invoke leaves $a2/$a3 holding stale register-file values
 * (which can be truncated host pointers) that the callee then dereferences.
 * Same nested-dispatch contract as call_guest: clean targets run through
 * clean_try_dispatch (wrappers marshal $a0-$a3), everything else goes
 * through psx_dispatch_call; caller arg/ra/pc regs preserved. */
uint32_t call_guest4(uint32_t fn, uint32_t a0, uint32_t a1,
                     uint32_t a2, uint32_t a3)
{
    CPUState *cpu = g_clean_cpu;
    uint32_t r0, r1, r2, r3, r8, ra, pc, v0;
    if (!cpu || fn == 0) return 0;
    r0 = cpu->gpr[4]; r1 = cpu->gpr[5];
    r2 = cpu->gpr[6]; r3 = cpu->gpr[7];
    /* Guest `jalr` sites that reach here load the target into $t0 first
     * (prim_task_run's `lw $t0,0xC($s2); jalr $ra,$t0`), so the callee
     * observes $t0 == fn. Reproduce that: some emit entries are mid-function
     * PCs (e.g. 0x8018A514 inside prim_task_run) whose first insn is
     * `sw $s6,0x3E0($t0)` — a stale $t0 turns that into an AdES. */
    r8 = cpu->gpr[8];
    ra = cpu->gpr[31]; pc = cpu->pc; v0 = cpu->gpr[2];
    cpu->gpr[4] = a0; cpu->gpr[5] = a1;
    cpu->gpr[6] = a2; cpu->gpr[7] = a3;
    cpu->gpr[8] = fn;
    if (clean_try_dispatch(cpu, fn)) {
        uint32_t r = cpu->gpr[2];
        cpu->gpr[4] = r0; cpu->gpr[5] = r1;
        cpu->gpr[6] = r2; cpu->gpr[7] = r3;
        cpu->gpr[8] = r8;
        cpu->gpr[31] = ra; cpu->pc = pc; cpu->gpr[2] = v0;
        return r;
    }
    {
        uint32_t sp = cpu->gpr[29];
        if (ra != 0) {
            cpu->gpr[31] = ra;
            psx_dispatch_call(cpu, fn, ra);
        } else {
            cpu->gpr[31] = BR2_NESTED_RA;
            psx_dispatch_call(cpu, fn, 0);
        }
        cpu->gpr[29] = sp;
    }
    {
        uint32_t r = cpu->gpr[2];
        cpu->gpr[4] = r0; cpu->gpr[5] = r1;
        cpu->gpr[6] = r2; cpu->gpr[7] = r3;
        cpu->gpr[8] = r8;
        cpu->gpr[31] = ra; cpu->pc = pc; cpu->gpr[2] = v0;
        return r;
    }
}

/* br2_call_generated — invoke the recompiled (generated) implementation of
 * a guest function, bypassing clean_try_dispatch entirely.  Used by clean
 * ports whose guest counterpart crosses BIOS kernel-call boundaries that
 * need full guest-stack/ra fidelity (kernel-object validation, thread
 * context).  Args go in $a0-$a3; return value in $v0. */
uint32_t br2_call_generated(uint32_t fn, uint32_t a0, uint32_t a1,
                            uint32_t a2, uint32_t a3)
{
    CPUState *cpu = g_clean_cpu;
    uint32_t ra, pc, sp, s0, s1, s2, s3;
    if (!cpu || fn == 0) return 0;
    /* Bail-unwind in flight (g_psx_call_bail): a prior generated frame detected
     * wild flow and is unwinding host frames toward the outermost dispatch. Do
     * NOT start a fresh guest call here — it would inherit the stale bail and
     * its CPS continuation would be cut short (the cd_ext_init_once wedge:
     * OpenEvent never ran because a null jalr in cd_chan_boot_init's sibling
     * left bail set). Return $v0 untouched so the unwind's cpu->pc / $ra /
     * $sp survive intact up to the flatten point. */
    if (g_psx_call_bail) return cpu->gpr[2];
    ra = cpu->gpr[31]; pc = cpu->pc; sp = cpu->gpr[29];
    s0 = cpu->gpr[16]; s1 = cpu->gpr[17]; s2 = cpu->gpr[18]; s3 = cpu->gpr[19];
    cpu->gpr[4] = a0; cpu->gpr[5] = a1;
    cpu->gpr[6] = a2; cpu->gpr[7] = a3;
    if (ra != 0) {
        cpu->gpr[31] = ra;
        psx_dispatch_call(cpu, fn, ra);
    } else {
        cpu->gpr[31] = BR2_NESTED_RA;
        psx_dispatch_call(cpu, fn, 0);
    }
    /* The callee (or a nested frame it reached) began a bail unwind: cpu->pc
     * now holds the wild-flow target the outermost dispatch must resume at.
     * Restoring the saved pc/ra/sp here would clobber that target and strand
     * the unwind, so leave every guest register exactly as the unwind left it. */
    if (g_psx_call_bail) return cpu->gpr[2];
    cpu->gpr[31] = ra; cpu->gpr[29] = sp; cpu->pc = pc;
    cpu->gpr[16] = s0; cpu->gpr[17] = s1;
    cpu->gpr[18] = s2; cpu->gpr[19] = s3;
    return cpu->gpr[2];
}

/* gpu_invoke — libgpu syscall gateway. gfx.c/cd.c resolve entries in the
 * game's GPU function table (guest addrs of the libgpu impls: DrawOTag,
 * LoadImage, ClearImage, ...) and hand them here with a0-a3. This is a
 * normal guest `jal` with four args, so run the target through the same
 * nested-dispatch contract as br2_call_generated and return $v0. The weak
 * no-op in game/bind.c only applies to the standalone selftest arena. */
uint32_t gpu_invoke(uint32_t fn, uint32_t a0, uint32_t a1, uint32_t a2, uint32_t a3)
{
    return br2_call_generated(fn, a0, a1, a2, a3);
}

/* Kernel syscall wrappers — guest 0x8018E300 = `li a0,1; syscall 0`
 * (EnterCriticalSection/DI, returns old IEc in $v0) and 0x8018E310 =
 * `li a0,2; syscall 0` (ExitCriticalSection/EI). Routed through the real
 * psx_syscall so IEc/IM[2] in COP0 SR change exactly as generated code
 * would do it. */
extern int psx_syscall(CPUState *cpu, uint32_t code);

void FUN_8018e300(void)
{
    CPUState *cpu = g_clean_cpu;
    if (!cpu) return;
    cpu->gpr[4] = 1;
    psx_syscall(cpu, 0);
}

void FUN_8018e310(uint32_t unused)
{
    CPUState *cpu = g_clean_cpu;
    (void)unused;
    if (!cpu) return;
    cpu->gpr[4] = 2;
    psx_syscall(cpu, 0);
}

uint32_t bios_svc(uint32_t table, uint32_t svc, uint32_t a0, uint32_t a1)
{
    uint32_t ra;
    CPUState *cpu = g_clean_cpu;
    if (!cpu) return 0;
    ra = cpu->gpr[31];
    svc_record(table, svc, a0, a1, cpu->gpr[6], cpu->gpr[7], ra);
    {
        uint32_t v = svc_call(table, svc, a0, a1, cpu->gpr[6], cpu->gpr[7]);
        g_svc_ring[(g_svc_ring_n - 1) % BR2_SVC_RING].v0 = v;
        return v;
    }
}

/* Six-arg variant: some kernel services consume a2/a3 as well (the guest
 * trampoline only sets $t1/$t2 and forwards whatever the caller left in
 * a0-a3). */
uint32_t bios_svc6(uint32_t table, uint32_t svc,
                   uint32_t a0, uint32_t a1, uint32_t a2, uint32_t a3)
{
    uint32_t ra;
    CPUState *cpu = g_clean_cpu;
    if (!cpu) return 0;
    ra = cpu->gpr[31];
    svc_record(table, svc, a0, a1, a2, a3, ra);
    {
        uint32_t v = svc_call(table, svc, a0, a1, a2, a3);
        g_svc_ring[(g_svc_ring_n - 1) % BR2_SVC_RING].v0 = v;
        return v;
    }
}

